SELECT * FROM( /*债券存续期 有效数据*/ SELECT * FROM ( SELECT '${PAGE_DATE_STATUS05}' statusValid, T1.TOTLE_TRADE_ID busiCode, T5.TYPE_8 finprodType2, nvl(t3.PA_BUSS_TYPE, T1.TG_BUSI_TYPE) paBussType, decode(order2.portfolio_id,null,ppTemp.portfolio_id,order2.portfolio_id) portfolioId, decode(order2.portfolio_name,null,ppTemp.portfolio_name,order2.portfolio_name) portfolioName, NVL(T1.SEC_MANAGE_ACCT_ID, T1.CHL_ID) secManageAcctId, nvl(SAI.SEC_ACCT_NAME, fp.FINPROD_NAME) secAcctName, T4.FINPROD_MARKET_ID finprodMarketId, T4.FINPROD_ABBR finprodAbbr, to_char(T1.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(T1.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, decode(order2.settle_amt,null,spo.settle_amt,order2.settle_amt) tradeAmt/*实收本息总额*/, null tradeAmt2, null shareAmt, T1.CCY ccy, to_char(T1.SETTLE_DATE, 'yyyy-MM-dd') tradeDate/*资金到账日*/, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ SI.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType, NULL workflowId FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN TRD_DEAL_TOTAL_ADD wtdta on t1.totle_trade_ID = WTDTA.TOTLE_TRADE_ID LEFT JOIN PTL_PORTFOLIO T2 ON T2.PORTFOLIO_ID = T1.PORTFOLIO_ID LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T5 ON T1.FINPROD_ID = T5.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID LEFT JOIN SYS_USER SU ON SU.USER_NAME = T1.CREATE_USER LEFT JOIN SYS_DEPARTMENT SD ON SD.DEPT_CODE = SU.DEPT_CODE LEFT JOIN SYS_INSTITUTION SI ON SI.INSTITUTION_CODE = SD.INSTITUTION_CODE LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TEMPT1 ON T1.TOTLE_TRADE_ID = TEMPT1.P_TOTLE_TRADE_ID LEFT JOIN orderTemp order2 on TEMPT1.TOTLE_TRADE_ID = order2.TRADE_ID left join trd_product_deal tpd on order2.TRADE_ID is null and tpd.totle_trade_id = t1.totle_trade_id left join STL_PAY_ORDERS spo on spo.trade_id = tpd.trade_id left join ptl_portfolio ppTemp on ppTemp.portfolio_id = spo.portfolio_id WHERE T1.TRADE_STATUS = #{TRADE_STATUS01} AND nvl(T1.IS_OVERDUE_DEAL,#{YESNO_N}) = #{YESNO_N} AND wtdta.MP_FINPROD_ID IS NULL AND T1.IS_CANCEL = #{YESNO_N} AND T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF01} AND T1.TRADE_MARKET in ('03','04')
AND T1.TOTLE_TRADE_ID = #{busiCode}
AND T1.P_TOTLE_TRADE_ID IS NULL
AND (EXISTS( select 1 from TRD_FIN_PRODUCT_DEAL_TOTAL DEAL
LEFT JOIN TRD_PRODUCT_DEAL tpd ON tpd.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD tpda ON tpd.TRADE_ID = tpda.TRADE_ID
where (DEAL.P_TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID OR (DEAL.PS IN (#{PS_T07},#{PS_T08},#{PS_T09},#{PST22},#{PST23},#{PST24}) AND DEAL.TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID AND tpd.TRADE_MARKET = #{TRADE_PLACE_01}))
and (DEAL.PORTFOLIO_ID OR tpda.PORTFOLIO_ID ) ) or T1.PS='T39') ORDER BY T1.MDATE DESC) union all /*质押式回购存续期*/ SELECT * FROM ( SELECT '${PAGE_DATE_STATUS05}' statusValid, T1.TOTLE_TRADE_ID busiCode, T5.TYPE_8 finprodType2, nvl(t3.PA_BUSS_TYPE, T1.TG_BUSI_TYPE) paBussType, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, NVL(T1.SEC_MANAGE_ACCT_ID, T1.CHL_ID) secManageAcctId, nvl(SAI.SEC_ACCT_NAME, fp.FINPROD_NAME) secAcctName, NULL finprodMarketId, NULL finprodAbbr, to_char(T41.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(T41.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, T1.TRADE_AMT tradeAmt,/*实收本息总额*/ null tradeAmt2, null shareAmt, T1.CCY ccy, to_char(T1.SETTLE_DATE, 'yyyy-MM-dd') tradeDate, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ SI.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType/*交易方向*/, null workflowId FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_TRADE_PRODUCT T41 ON T1.FINPROD_ID = T41.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T5 ON T41.FINPROD_ID = T5.FINPROD_ID LEFT JOIN PTL_TRADE PT ON T1.FINPROD_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO T2 ON PT.PORTFOLIO_ID = T2.PORTFOLIO_ID LEFT JOIN TRD_PRODUCT_DEAL ptpd on ptpd.TRADE_ID = T4.FINPROD_ID LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID LEFT JOIN SYS_USER SU ON SU.USER_NAME = T1.CREATE_USER LEFT JOIN SYS_DEPARTMENT SD ON SD.DEPT_CODE = SU.DEPT_CODE LEFT JOIN SYS_INSTITUTION SI ON SI.INSTITUTION_CODE = SD.INSTITUTION_CODE LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID WHERE T2.INVEST_YESORNO = 'Y' AND T1.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TGF02}, #{FINPROD_TYPE_TGF03}) and T1.PORTFOLIO_ID and t1.TRADE_STATUS = #{TRADE_STATUS01} and t1.IS_CANCEL = #{YES_OR_NO_N} and t1.PS in (#{PST07},#{PST56},#{PS_TQZZ},#{PS_YQFS},'T93', 'T94', 'T96')
ORDER BY T1.TRADE_DATE DESC) union all SELECT * FROM ( SELECT '${PAGE_DATE_STATUS05}' statusValid, T1.TOTLE_TRADE_ID busiCode, T5.TYPE_8 finprodType2, nvl(t3.PA_BUSS_TYPE, T1.TG_BUSI_TYPE) paBussType, case when T1.PORTFOLIO_ID is not null then T1.PORTFOLIO_ID else order2.portfolio_id end as portfolioId, case when T1.PORTFOLIO_ID is not null then T2.PORTFOLIO_NAME else order2.portfolio_name end as portfolioName, NVL(T1.SEC_MANAGE_ACCT_ID, T1.CHL_ID) secManageAcctId, nvl(SAI.SEC_ACCT_NAME, fp.FINPROD_NAME) secAcctName, T4.FINPROD_MARKET_ID finprodMarketId, T4.FINPROD_ABBR finprodAbbr, to_char(T1.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(T1.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, decode(order2.settle_amt,null,T1.FPRICE_AMT,order2.settle_amt) tradeAmt/*实收本息总额*/, null tradeAmt2, null shareAmt, T1.CCY ccy, to_char(T1.TRADE_DATE, 'yyyy-MM-dd') tradeDate/*资金到账日*/, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ SI.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType, null workflowId FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN PTL_PORTFOLIO T2 ON T2.PORTFOLIO_ID = T1.PORTFOLIO_ID LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T5 on T5.FINPROD_ID = T1.FINPROD_ID LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID LEFT JOIN SYS_USER SU ON SU.USER_NAME = T1.CREATE_USER LEFT JOIN SYS_DEPARTMENT SD ON SD.DEPT_CODE = SU.DEPT_CODE LEFT JOIN SYS_INSTITUTION SI ON SI.INSTITUTION_CODE = SD.INSTITUTION_CODE LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TEMPT1 ON T1.TOTLE_TRADE_ID = TEMPT1.P_TOTLE_TRADE_ID LEFT JOIN orderTemp order2 on TEMPT1.TOTLE_TRADE_ID = order2.TRADE_ID WHERE T1.TRADE_STATUS = #{TRADE_STATUS01} AND nvl(T1.IS_OVERDUE_DEAL,#{YESNO_N}) = #{YESNO_N} AND T1.IS_CANCEL = #{YESNO_N} AND T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF07} AND T1.P_TOTLE_TRADE_ID is null AND EXISTS( select 1 from TRD_FIN_PRODUCT_DEAL_TOTAL DEAL where (DEAL.P_TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID or deal.TOTLE_TRADE_ID = t1.TOTLE_TRADE_ID) and (DEAL.PORTFOLIO_ID OR T1.PORTFOLIO_ID )
and (DEAL.PORTFOLIO_ID IN
#{item}
OR T1.PORTFOLIO_ID IN
#{item} )
)
ORDER BY T1.MDATE DESC) union all SELECT * FROM ( SELECT '${PAGE_DATE_STATUS05}' statusValid, T1.TOTLE_TRADE_ID busiCode, T5.TYPE_8 finprodType2, nvl(t3.PA_BUSS_TYPE, T1.TG_BUSI_TYPE) paBussType, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, NVL(T1.SEC_MANAGE_ACCT_ID, T1.CHL_ID) secManageAcctId, nvl(SAI.SEC_ACCT_NAME, fp.FINPROD_NAME) secAcctName, null finprodMarketId, null finprodAbbr, to_char(T1.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(T1.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, T1.TRADE_AMT tradeAmt/*实付本息和*/, null tradeAmt2, null shareAmt, T1.CCY ccy, to_char(T1.SETTLE_DATE, 'yyyy-MM-dd') tradeDate/*资金到账日*/, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ SI.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType, null workflowId FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN PTL_PORTFOLIO T2 ON T2.PORTFOLIO_ID = T1.PORTFOLIO_ID LEFT JOIN FIN_TRADE_PRODUCT T9 ON T1.FINPROD_ID = T9.FINPROD_ID and t1.BRANCH = T9.BRANCH LEFT JOIN PTL_TRADE PT ON T1.FINPROD_ID = PT.BUSI_NO LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN SYS_USER SU ON SU.USER_NAME = T1.CREATE_USER LEFT JOIN SYS_DEPARTMENT SD ON SD.DEPT_CODE = SU.DEPT_CODE LEFT JOIN SYS_INSTITUTION SI ON SI.INSTITUTION_CODE = SD.INSTITUTION_CODE LEFT JOIN FIN_PRODUCT_TYPE T5 on T5.FINPROD_ID = T1.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID WHERE T1.BUSI_TYPE = #{COMMON_BUSINESS_TYPETRD11} and t1.PORTFOLIO_ID and t1.TRADE_STATUS = #{TRADE_STATUS01} and t1.IS_CANCEL = #{YES_OR_NO_N} AND T2.INVEST_YESORNO = 'Y'
#{item}
AND T1.SEC_MANAGE_ACCT_ID = #{secManageAcctId}
AND T4.FINPROD_MARKET_ID = #{finprodMarketId}
AND nvl(t3.PA_BUSS_TYPE, T1.TG_BUSI_TYPE) = #{paBizType}
AND T1.SETTLE_DATE >= to_date(#{tradeDateStart}, 'yyyy-MM-dd')
AND T1.SETTLE_DATE <= to_date(#{tradeDateEnd}, 'yyyy-MM-dd')
AND FP.FINPROD_ID = #{chlId}
AND T5.TYPE_8 = #{finprodType2}
AND (T2.PORTFOLIO_ID IN (#{item} ) or T2.PARENT_PORTFOLIO_ID IN (#{item} ) )
ORDER BY T1.TRADE_DATE DESC)
union all SELECT * from( SELECT #{PAGE_DATE_STATUS05} statusValid, T1.TOTLE_TRADE_ID busiCode, T5.TYPE_8 finprodType2, nvl(t3.PA_BUSS_TYPE, T1.TG_BUSI_TYPE) paBussType, dealAdd.PORTFOLIO_ID portfolioId, pp.PORTFOLIO_NAME portfolioName, NVL(T1.SEC_MANAGE_ACCT_ID, T1.CHL_ID) secManageAcctId, nvl(SAI.SEC_ACCT_NAME, fp.FINPROD_NAME) secAcctName, T4.FINPROD_MARKET_ID finprodMarketId, T4.FINPROD_ABBR finprodAbbr, null vDate/*计息开始日*/, null mDate/*计息结束日*/, decode(deal.INT_AMT,null,T1.INT_AMT,deal.INT_AMT) tradeAmt/*实收本息总额*/, null tradeAmt2, T1.SHARE_AMT shareAmt, T1.CCY ccy, to_char(T1.TRADE_DATE, 'yyyy-MM-dd') tradeDate/*资金到账日*/, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ SI.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType, null workflowId from TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID left join FIN_PRODUCT T4 on T4.FINPROD_ID =T1.FINPROD_ID LEFT JOIN PTL_PORTFOLIO T2 ON T2.PORTFOLIO_ID = T1.PORTFOLIO_ID inner join FIN_PRODUCT_TYPE T5 on T5.FINPROD_ID =T1.FINPROD_ID LEFT JOIN FIN_PRODUCT FP ON FP.FINPROD_ID =T1.CHL_ID LEFT JOIN SYS_USER SU ON SU.USER_NAME = T1.CREATE_USER LEFT JOIN SYS_DEPARTMENT SD ON SD.DEPT_CODE = SU.DEPT_CODE LEFT JOIN SYS_INSTITUTION SI ON SI.INSTITUTION_CODE = SD.INSTITUTION_CODE LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID LEFT JOIN TRD_PRODUCT_DEAL deal on deal.TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID and deal.TRADE_STATUS = '01' left join TRD_PRODUCT_DEAL_ADD dealAdd on deal.TRADE_ID = dealAdd.TRADE_ID left join PTL_PORTFOLIO pp on dealAdd.PORTFOLIO_ID = pp.PORTFOLIO_ID and nvl(pp.PARENT_PORTFOLIO_ID,'null') = 'null' where T1.PS IN (#{PS_T12},#{PS_T13},#{PS_T11}) and T5.TYPE_6 IN (#{FUND_ASSET_TYPE_F01},#{FUND_ASSET_TYPE_F02}) and T1.TRADE_STATUS = #{TRADE_STATUS01} and T1.IS_CANCEL = #{YESNO_N} )
union all /*多种分红类型基金有效*/ SELECT * FROM ( SELECT #{PAGE_DATE_STATUS05} statusValid,
,NULL workflowId from TRD_PRODUCT_DEAL T1
where T1.PS IN (#{PS_T12},#{PS_T13},#{PS_T11}) and T5.TYPE_6 IN (#{FUND_ASSET_TYPE_F01},#{FUND_ASSET_TYPE_F02}) and T1.TRADE_STATUS = #{TRADE_STATUS01} and T1.IS_CANCEL = #{YESNO_N} and nvl(pp.PARENT_PORTFOLIO_ID,'null') = 'null'
)
union all SELECT * from( SELECT #{PAGE_DATE_STATUS05} statusValid, T1.TOTLE_TRADE_ID busiCode, T5.TYPE_8 finprodType2, nvl(t3.PA_BUSS_TYPE, T1.TG_BUSI_TYPE) paBussType, dealAdd.PORTFOLIO_ID portfolioId, pp.PORTFOLIO_NAME portfolioName, NVL(T1.SEC_MANAGE_ACCT_ID, T1.CHL_ID) secManageAcctId, nvl(SAI.SEC_ACCT_NAME, fp.FINPROD_NAME) secAcctName, T4.FINPROD_MARKET_ID finprodMarketId, T4.FINPROD_ABBR finprodAbbr, null vDate/*计息开始日*/, null mDate/*计息结束日*/, decode(deal.INT_AMT,null,T1.INT_AMT,deal.INT_AMT) tradeAmt/*实收本息总额*/, null tradeAmt2, T1.SHARE_AMT shareAmt, T1.CCY ccy, to_char(T1.TRADE_DATE, 'yyyy-MM-dd') tradeDate/*资金到账日*/, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ SI.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType, null workflowId from TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID left join FIN_PRODUCT T4 on T4.FINPROD_ID =T1.FINPROD_ID LEFT JOIN PTL_PORTFOLIO T2 ON T2.PORTFOLIO_ID = T1.PORTFOLIO_ID inner join FIN_PRODUCT_TYPE T5 on T5.FINPROD_ID =T1.FINPROD_ID LEFT JOIN FIN_PRODUCT FP ON FP.FINPROD_ID =T1.CHL_ID LEFT JOIN SYS_USER SU ON SU.USER_NAME = T1.CREATE_USER LEFT JOIN SYS_DEPARTMENT SD ON SD.DEPT_CODE = SU.DEPT_CODE LEFT JOIN SYS_INSTITUTION SI ON SI.INSTITUTION_CODE = SD.INSTITUTION_CODE LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID LEFT JOIN TRD_PRODUCT_DEAL deal on deal.TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID and deal.TRADE_STATUS = '01' left join TRD_PRODUCT_DEAL_ADD dealAdd on deal.TRADE_ID = dealAdd.TRADE_ID left join PTL_PORTFOLIO pp on dealAdd.PORTFOLIO_ID = pp.PORTFOLIO_ID and nvl(pp.PARENT_PORTFOLIO_ID,'null') = 'null' where T1.PS IN (#{PS_T12},#{PS_T13},#{PS_T11}) and T4.PROFIT_TYPE IN (#{PROFIT_TYPE_JZ}, #{PROFIT_TYPE_HB}) and T4.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F17} and T1.TRADE_STATUS = #{TRADE_STATUS01} and T1.IS_CANCEL = #{YESNO_N} ) union all SELECT * FROM ( SELECT '${PAGE_DATE_STATUS05}' statusValid, T1.TOTLE_TRADE_ID busiCode, T5.TYPE_8 finprodType2, nvl(t3.PA_BUSS_TYPE, T1.TG_BUSI_TYPE) paBussType, order2.portfolio_id portfolioId, order2.portfolio_name portfolioName, NVL(T1.SEC_MANAGE_ACCT_ID, T1.CHL_ID) secManageAcctId, nvl(SAI.SEC_ACCT_NAME, fp.FINPROD_NAME) secAcctName, T4.FINPROD_MARKET_ID finprodMarketId, T4.FINPROD_ABBR finprodAbbr, to_char(T1.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(T1.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, decode(order2.settle_amt,null, T1.TRADE_AMT,order2.settle_amt) tradeAmt/*实收本息总额*/, null tradeAmt2, null shareAmt, T4.CCY ccy, to_char(T1.TRADE_DATE, 'yyyy-MM-dd') tradeDate/*资金到账日*/, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ SI.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType, null workflowId FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT PF ON T1.CHL_ID = PF.FINPROD_ID LEFT JOIN PTL_PORTFOLIO T2 ON T2.PORTFOLIO_ID = T1.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID LEFT JOIN SYS_USER SU ON SU.USER_NAME = T1.CREATE_USER LEFT JOIN SYS_DEPARTMENT SD ON SD.DEPT_CODE = SU.DEPT_CODE LEFT JOIN SYS_INSTITUTION SI ON SI.INSTITUTION_CODE = SD.INSTITUTION_CODE LEFT JOIN FIN_PRODUCT_TYPE T5 on T5.FINPROD_ID = T1.FINPROD_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TEMPT1 ON T1.TOTLE_TRADE_ID = TEMPT1.P_TOTLE_TRADE_ID LEFT JOIN orderTemp order2 on TEMPT1.TOTLE_TRADE_ID = order2.TRADE_ID WHERE T1.TRADE_STATUS = #{TRADE_STATUS01} AND T1.PORTFOLIO_ID IS NULL AND nvl(T1.IS_OVERDUE_DEAL,#{YESNO_N}) = #{YESNO_N} AND T1.IS_CANCEL = #{YESNO_N} AND T1.BUSI_TYPE = #{TRD15} AND T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF17} AND T4.PROFIT_TYPE = #{PROFIT_TYPE02} AND EXISTS (SELECT 1 FROM TRD_FIN_PRODUCT_DEAL_TOTAL DEAL where DEAL.P_TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID AND DEAL.PORTFOLIO_ID )
ORDER BY T1.FINPROD_ID, T1.TRADE_DATE DESC, T1.MDATE DESC) union all SELECT * FROM ( SELECT '${PAGE_DATE_STATUS05}' statusValid, T1.TOTLE_TRADE_ID busiCode, T5.TYPE_8 finprodType2, nvl(t3.PA_BUSS_TYPE, T1.TG_BUSI_TYPE) paBussType, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, NVL(T1.SEC_MANAGE_ACCT_ID, T1.CHL_ID) secManageAcctId, nvl(SAI.SEC_ACCT_NAME, fp.FINPROD_NAME) secAcctName, NULL finprodMarketId, NULL finprodAbbr, to_char(T1.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(T1.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, T1.TRADE_AMT tradeAmt/*实收本息总额*/, null tradeAmt2, null shareAmt, T1.CCY ccy, to_char(T1.SETTLE_DATE, 'yyyy-MM-dd') tradeDate/*资金到账日*/, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ SI.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType, null workflowId FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_TRADE_PRODUCT T41 ON T1.FINPROD_ID = T41.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T5 ON T41.FINPROD_ID = T5.FINPROD_ID LEFT JOIN PTL_TRADE PT ON T1.FINPROD_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO T2 ON PT.PORTFOLIO_ID = T2.PORTFOLIO_ID LEFT JOIN SYS_USER SU ON SU.USER_NAME = T1.CREATE_USER LEFT JOIN SYS_DEPARTMENT SD ON SD.DEPT_CODE = SU.DEPT_CODE LEFT JOIN SYS_INSTITUTION SI ON SI.INSTITUTION_CODE = SD.INSTITUTION_CODE LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID WHERE T2.INVEST_YESORNO = 'Y' AND T1.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TGF04}, #{FINPROD_TYPE_TGF05}) and T1.PORTFOLIO_ID and t1.TRADE_STATUS = #{TRADE_STATUS01} and t1.IS_CANCEL = #{YES_OR_NO_N} and t1.PS = #{PST07}
