ID and deal.TRADE_STATUS = '01' left join TRD_PRODUCT_DEAL_ADD dealAdd on deal.TRADE_ID = dealAdd.TRADE_ID left join PTL_PORTFOLIO pp on dealAdd.PORTFOLIO_ID = pp.PORTFOLIO_ID and nvl(pp.PARENT_PORTFOLIO_ID,'null') = 'null' WHERE T1.P_TRADE_ID IS NULL AND T1.FINPROD_TYPE2 = #{F10} and nvl(T2.PARENT_PORTFOLIO_ID,'null') = 'null' ) union all SELECT * FROM ( SELECT DISTINCT '${PAGE_DATE_STATUS05}' statusValid, T1.TOTLE_TRADE_ID busiCode, T5.TYPE_8 finprodType2, nvl(t3.PA_BUSS_TYPE, T1.TG_BUSI_TYPE) paBussType, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, NVL(T1.SEC_MANAGE_ACCT_ID, T1.CHL_ID) secManageAcctId, nvl(SAI.SEC_ACCT_NAME, fp.FINPROD_NAME) secAcctName, T4.FINPROD_MARKET_ID finprodMarketId, T4.FINPROD_ABBR finprodAbbr, to_char(T21.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(T21.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, T21.TRADE_AMT tradeAmt/*实收本息总额*/, T31.TRADE_AMT tradeAmt2/*实收本息总额*/, null shareAmt, T21.CCY ccy, to_char(T1.SETTLE_DATE, 'yyyy-MM-dd') tradeDate/*资金到账日*/, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ SI.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType, null workflowId FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T3 ON T3.TOTLE_TRADE_ID = T1.TOTLE_TRADE_ID LEFT JOIN FIN_TRADE_PRODUCT T41 ON T1.FINPROD_ID = T41.FINPROD_ID AND T1.BRANCH = T41.BRANCH LEFT JOIN TRD_PRODUCT_DEAL T21 ON T1.TOTLE_TRADE_ID = T21.TOTLE_TRADE_ID AND ((T21.PS = #{psR} and T41.IRS_TYPE = #{irsType01}) OR (T21.PS = #{psP} and T41.IRS_TYPE = #{irsType02})) LEFT JOIN TRD_PRODUCT_DEAL T31 ON T1.TOTLE_TRADE_ID = T31.TOTLE_TRADE_ID AND ((T31.PS = #{psR} and T41.IRS_TYPE = #{irsType02}) OR (T31.PS = #{psP} and T41.IRS_TYPE = #{irsType01})) LEFT JOIN PTL_TRADE PT ON NVL(NVL(T21.P_TRADE_ID, T21.TRADE_ID), NVL(T31.P_TRADE_ID, T31.TRADE_ID)) = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO T2 ON PT.PORTFOLIO_ID = T2.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN SYS_USER SU ON SU.USER_NAME = T1.CREATE_USER LEFT JOIN SYS_DEPARTMENT SD ON SD.DEPT_CODE = SU.DEPT_CODE LEFT JOIN SYS_INSTITUTION SI ON SI.INSTITUTION_CODE = SD.INSTITUTION_CODE LEFT JOIN FIN_PRODUCT_TYPE T5 on T5.FINPROD_ID = T1.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID WHERE T1.TRADE_STATUS = #{TRADE_STATUS01} AND T1.IS_CANCEL = #{YESNO_N} AND T41.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF14} AND T2.INVEST_YESORNO='Y' AND T1.P_TRADE_ID IS NULL/*撤销的数据不展示*/ AND T1.P_TOTLE_TRADE_ID IS NULL
AND T1.PORTFOLIO_ID ) union all select * from ( SELECT '${PAGE_DATE_STATUS05}' statusValid, T1.TOTLE_TRADE_ID busiCode, T5.TYPE_8 finprodType2, nvl(t3.PA_BUSS_TYPE, T1.TG_BUSI_TYPE) paBussType, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, NVL(T1.SEC_MANAGE_ACCT_ID, T1.CHL_ID) secManageAcctId, nvl(SAI.SEC_ACCT_NAME, fp.FINPROD_NAME) secAcctName, T4.FINPROD_MARKET_ID finprodMarketId, T4.FINPROD_ABBR finprodAbbr, to_char(FTP.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(FTP.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, T1.TRADE_AMT tradeAmt/*实收本息总额*/, null tradeAmt2, null shareAmt, T1.CCY ccy, to_char(T1.TRADE_DATE, 'yyyy-MM-dd') tradeDate/*资金到账日*/, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ SI.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType, null workflowId from TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TFDT ON T1.FINPROD_ID = TFDT.TOTLE_TRADE_ID LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_TRADE_PRODUCT FTP ON T1.FINPROD_ID = FTP.FINPROD_ID LEFT JOIN PTL_PORTFOLIO T2 ON T2.PORTFOLIO_ID = T1.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT_TYPE T5 ON T1.FINPROD_ID = T5.FINPROD_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN SYS_USER SU ON SU.USER_NAME = T1.CREATE_USER LEFT JOIN SYS_DEPARTMENT SD ON SD.DEPT_CODE = SU.DEPT_CODE LEFT JOIN SYS_INSTITUTION SI ON SI.INSTITUTION_CODE = SD.INSTITUTION_CODE LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID WHERE T1.TRADE_STATUS = #{TRADE_STATUS01} AND T1.IS_CANCEL = #{YESNO_N} AND T1.PS IN ('T59','T60','T61') AND T1.FINPROD_TYPE2 = 'F35' AND T5.TYPE_8 = 'F18' and T1.TRADE_STATUS = #{TRADE_STATUS_01} ) union all select * from ( SELECT '${PAGE_DATE_STATUS05}' statusValid, T1.TOTLE_TRADE_ID busiCode, T5.TYPE_8 finprodType2, nvl(t3.PA_BUSS_TYPE, T1.TG_BUSI_TYPE) paBussType, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, NVL(T1.SEC_MANAGE_ACCT_ID, T1.CHL_ID) secManageAcctId, nvl(SAI.SEC_ACCT_NAME, fp.FINPROD_NAME) secAcctName, T4.FINPROD_MARKET_ID finprodMarketId, T4.FINPROD_ABBR finprodAbbr, to_char(T1.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(T1.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, T1.FPRICE_AMT tradeAmt/*实收本息总额*/, null tradeAmt2, null shareAmt, T1.CCY ccy, to_char(T1.TRADE_DATE, 'yyyy-MM-dd') tradeDate/*资金到账日*/, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ SI.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType, null workflowId FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN TRD_DEAL_TOTAL_ADD wtdta on t1.totle_trade_ID = WTDTA.TOTLE_TRADE_ID LEFT JOIN PTL_PORTFOLIO T2 ON T2.PORTFOLIO_ID = T1.PORTFOLIO_ID LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID LEFT JOIN SYS_USER SU ON SU.USER_NAME = T1.CREATE_USER LEFT JOIN SYS_DEPARTMENT SD ON SD.DEPT_CODE = SU.DEPT_CODE LEFT JOIN SYS_INSTITUTION SI ON SI.INSTITUTION_CODE = SD.INSTITUTION_CODE LEFT JOIN FIN_PRODUCT_TYPE T5 on T5.FINPROD_ID = T1.FINPROD_ID WHERE T1.FINPROD_TYPE2 = 'F01' AND T1.TRADE_STATUS = '01' AND T1.IS_CANCEL = 'N' AND T1.TG_BUSI_TYPE IN ('137', '138') AND wtdta.MP_FINPROD_ID IS NOT NULL AND T1.PORTFOLIO_ID
ORDER BY T1.MDATE ) )
