SELECT * FROM ( SELECT * FROM ( SELECT '${PAGE_DATE_STATUS06}' statusValid, T1.P_TRADE_ID busiCode, T5.TYPE_8 finprodType2, nvl(t3.PA_BUSS_TYPE, T1.TG_BUSI_TYPE) paBussType, decode(order2.portfolio_id,null,ppTemp.portfolio_id,order2.portfolio_id) portfolioId, decode(order2.portfolio_name,null,ppTemp.portfolio_name,order2.portfolio_name) portfolioName, NVL(T1.SEC_MANAGE_ACCT_ID, T1.CHL_ID) secManageAcctId, nvl(SAI.SEC_ACCT_NAME, fp.FINPROD_NAME) secAcctName, T4.FINPROD_MARKET_ID finprodMarketId, T4.FINPROD_ABBR finprodAbbr, to_char(T1.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(T1.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, decode(order2.settle_amt,null,spo.settle_amt,order2.settle_amt) tradeAmt/*实收本息总额*/, null tradeAmt2, null shareAmt, T1.CCY ccy, to_char(T1.SETTLE_DATE, 'yyyy-MM-dd') tradeDate/*资金到账日*/, T1.REMARK remark, SI.INSTITUTION_NAME institutionName, /*所属机构*/ SI.INSTITUTION_CODE institutionCode, T1.FINPROD_ID finprodId, T1.PS cashType, NULL workflowId FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN TRD_DEAL_TOTAL_ADD wtdta on t1.totle_trade_ID = WTDTA.TOTLE_TRADE_ID LEFT JOIN PTL_PORTFOLIO T2 ON T2.PORTFOLIO_ID = T1.PORTFOLIO_ID LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T5 ON T1.FINPROD_ID = T5.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SAI ON T1.SEC_MANAGE_ACCT_ID = SAI.SEC_ACCT_ID LEFT JOIN FIN_PRODUCT FP ON T1.CHL_ID = FP.FINPROD_ID LEFT JOIN SYS_USER SU ON SU.USER_NAME = T1.CREATE_USER LEFT JOIN SYS_DEPARTMENT SD ON SD.DEPT_CODE = SU.DEPT_CODE LEFT JOIN SYS_INSTITUTION SI ON SI.INSTITUTION_CODE = SD.INSTITUTION_CODE LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TEMPT1 ON T1.TOTLE_TRADE_ID = TEMPT1.P_TOTLE_TRADE_ID LEFT JOIN orderTemp order2 on TEMPT1.TOTLE_TRADE_ID = order2.TRADE_ID left join trd_product_deal tpd on order2.TRADE_ID is null and tpd.totle_trade_id = t1.P_TRADE_ID and tpd.is_cancel = #{YESNO_N} left join STL_PAY_ORDERS spo on spo.trade_id = tpd.trade_id left join ptl_portfolio ppTemp on ppTemp.portfolio_id = spo.portfolio_id WHERE T1.TRADE_STATUS = #{TRADE_STATUS03} AND nvl(T1.IS_OVERDUE_DEAL,#{YESNO_N}) = #{YESNO_N} AND wtdta.MP_FINPROD_ID IS NULL AND T1.BUSI_TYPE = #{TRD10} AND T1.FINPROD_TYPE2 = #{FINPROD_TYPE_TGF01} AND T1.TRADE_MARKET in ('03','04')
AND T1.P_TRADE_ID = #{busiCode}
AND T1.P_TOTLE_TRADE_ID IS NULL
AND (EXISTS( select 1 from TRD_FIN_PRODUCT_DEAL_TOTAL DEAL
LEFT JOIN TRD_PRODUCT_DEAL tpd ON tpd.TOTLE_TRADE_ID = DEAL.TOTLE_TRADE_ID LEFT JOIN TRD_PRODUCT_DEAL_ADD tpda ON tpd.TRADE_ID = tpda.TRADE_ID
